// SFCC-847 drawer/content/filters — accordion recipe. Tokens sourced from the Zimmermann
// Design System 2026 Figma (node wPiWmZZOVKnrENUWk2XWWm/40003890:151736 and /40003890:151742,
// audited 2026-09-16). Divider colour resolves to `alias/color/border/secondary` in Figma
// which binds to `#dddddd` — surfaced in this codebase as
// `--zimm-color-border-tertiary` (see foundation/colour.ts `border.tertiary`). Figma's N+1
// divider pattern (7 dividers for 6 accordions: top + between + bottom) is reproduced by
// giving each item both `borderTop` and `borderBottom`, with no `_first`/`_last` override.

export const ZimmAccordion = {
  parts: ['root', 'item', 'header', 'label', 'alwaysVisible', 'panel'],
  baseStyle: {
    root: {
      width: '100%',
    },
    // Every item carries both top and bottom borders so the accordion group reads as N+1
    // dividers between headers, matching Figma. Chakra's own AccordionItem defaults are
    // overridden here rather than layered on: the default `1px solid` uses the theme border
    // colour, not the drawer-specific tertiary token.
    item: {
      borderTop: 'var(--zimm-border-width-default) solid var(--zimm-color-border-tertiary)',
      borderBottom: 'var(--zimm-border-width-default) solid var(--zimm-color-border-tertiary)',
      // Collapse the shared edge between adjacent items so a single 1px line renders instead
      // of a doubled 2px seam. Only the last item keeps its own borderBottom.
      _notLast: {
        borderBottom: 'none',
      },
    },
    // Chakra's AccordionButton is a real <button>; these sx overrides layer over its defaults
    // (transparent bg, blackAlpha _hover, block layout). Cursor: pointer stays Chakra-owned.
    // paddingBlock 20px per row yields ~41px between adjacent header baselines (20 + 1px
    // border + 20), matching Figma's `Accordion group` gap-with-divider rhythm.
    header: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      width: '100%',
      paddingBlock: 'var(--zimm-scale-l)',
      paddingInline: 0,
      _hover: {
        backgroundColor: 'transparent',
      },
      _focusVisible: {
        // audit-allow: 2px matches Chakra's default focus-ring outline width; no dedicated
